import importlib.util,json,time,statistics
from pathlib import Path
paths={'reference':'/tmp/courier-x86-before-write-trace.so','candidate':str(next(Path('.build').glob('_x86_native*.so')))}
fns={}
for k,p in paths.items():
 spec=importlib.util.spec_from_file_location('_x86_native',p);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);fns[k]=m.run
out={k:[] for k in paths}
states=[]
for i in range(6):
 for key in (['reference','candidate'] if i%2==0 else ['candidate','reference']):
  regs=[0]*14;regs[12]=0x1000;regs[13]=2
  mem=bytearray(0x100000);mem[0x1000:0x1008]=bytes.fromhex('4001d8a30030ebf8')
  guard=bytearray([3])*len(mem);ports=bytearray(65536);events=bytearray(4*65536);ints=bytearray(1024)
  f=fns[key];f(regs,mem,guard,ports,events,10000,None,ints)
  start=time.process_time()
  for _ in range(80):f(regs,mem,guard,ports,events,65536,None,ints)
  out[key].append(time.process_time()-start);states.append((regs,mem))
assert all(s==states[0] for s in states)
med={k:statistics.median(v) for k,v in out.items()}
print(json.dumps({'runs':out,'medians':med,'candidate_cpu_change_percent':100*(med['candidate']/med['reference']-1),'states_match':True},indent=2))
